import "temporal-polyfill/global";
export { escape } from "deno-std/html/entities.js";
import { parse } from "deno-std/yaml/unstable-parse.js";
import { stringify } from "deno-std/yaml/unstable-stringify.js";
export { acceptsLanguages } from "deno-std/http/negotiation.js";
export { test as testFrontMatter } from "deno-std/front-matter/test.js";
export { extract as extractFrontMatter } from "deno-std/front-matter/yaml.js";
export * as posix from "deno-std/path/posix/mod.js";
export { basename, dirname, extname, fromFileUrl, globToRegExp, relative, SEPARATOR, } from "deno-std/path/mod.js";
export { format as formatBytes } from "deno-std/fmt/bytes.js";
export { decodeBase64, encodeBase64 } from "deno-std/encoding/base64.js";
export { contentType } from "deno-std/media-types/content-type.js";
const YAML_DATE = /^\d{4}-\d{2}-\d{2}$/;
const YAML_DATETIME = /^\d{4}-\d{2}-\d{2}[Tt\s]\d{2}:\d{2}:\d{2}$/;
const date = {
    tag: "tag:cms:date",
    kind: "scalar",
    resolve: (data) => typeof data === "string" && YAML_DATE.test(data),
    construct: (data) => Temporal.PlainDate.from(data),
    predicate: (data) => data instanceof Temporal.PlainDate,
    represent: (data) => data.toString(),
};
const datetime = {
    tag: "tag:cms:datetime",
    kind: "scalar",
    resolve: (data) => typeof data === "string" && YAML_DATETIME.test(data),
    construct: (data) => Temporal.PlainDateTime.from(data),
    predicate: (data) => data instanceof Temporal.PlainDateTime,
    represent: (data) => data.toString().replace("T", " "),
};
export function parseYaml(yaml) {
    return parse(yaml, {
        extraTypes: [date, datetime],
    });
}
export function stringifyYaml(yaml) {
    return stringify(yaml, {
        extraTypes: [date, datetime],
    });
}
